class TestCRAConsensusParameters:
    """Validate the immutable consensus parameters."""

    def test_frozen_dataclass(self):
        """Parameters must be immutable."""
        params = qkg.CRAConsensusParameters()
        with pytest.raises(AttributeError):
            params.key_rotation_ttl_seconds = 10.0

    def test_default_values(self):
        """Verify CRA consensus defaults."""
        params = qkg.CRAConsensusParameters()
        assert params.kyber_polynomial_modulus == 2**3328 - 1
        assert params.key_rotation_ttl_seconds == 5.0
        assert params.self_healing_budget == 3

    def test_ttl_positive(self):
        """TTL must be strictly positive."""
        with pytest.raises(ValueError):
            qkg.CRAConsensusParameters(key_rotation_ttl_seconds=0)

    def test_budget_positive(self):
        """Self-healing budget must be positive."""
        with pytest.raises(ValueError):
            qkg.CRAConsensusParameters(self_healing_budget=0)


