class TestKeyGeneration:
    """Validate Kyber-1024 key generation."""

    @pytest.mark.asyncio
    async def test_generate_keypair(self, mock_pyoqs):
        """Keypair generation must produce valid sizes."""
        gateway = qkg.QuantumKeyDistributionGateway()
        pk, sk = await gateway._generate_keypair()
        assert len(pk) == 64  # 32 bytes * 2 (mock)
        assert len(sk) == 128  # 64 bytes * 2 (mock)

    @pytest.mark.asyncio
    async def test_encapsulation_roundtrip(self, mock_pyoqs):
        """Encapsulation/decapsulation must be symmetric."""
        gateway = qkg.QuantumKeyDistributionGateway()
        pk, sk = await gateway._generate_keypair()
        ct, ss1 = await gateway._encapsulate(pk)
        ss2 = await gateway._decapsulate(sk, ct)
        assert ss1 == ss2

    def test_hmac_verification(self):
        """HMAC must verify correctly."""
        key = b"test_key" * 16
        message = b"test_message"
        mac = hmac.new(key, message, hashlib.sha256).digest()
        assert hmac.compare_digest(mac, hmac.new(key, message, hashlib.sha256).digest())

    def test_hmac_tamper_detection(self):
        """Tampered messages must fail HMAC verification."""
        key = b"test_key" * 16
        message = b"test_message"
        mac = hmac.new(key, message, hashlib.sha256).digest()
        tampered = message + b"X"
        assert not hmac.compare_digest(mac, hmac.new(key, tampered, hashlib.sha256).digest())


