class TestSelfHealing:
    """Validate self-healing budget enforcement (INV-003)."""

    @pytest.mark.asyncio
    async def test_budget_decrement_on_failure(self, mock_pyoqs):
        """Failed rotations must decrement the budget."""
        gateway = qkg.QuantumKeyDistributionGateway()
        gateway._consensus_params = qkg.CRAConsensusParameters(
            self_healing_budget=3
        )
        await gateway.initialize()
        # Force a failure
        with patch.object(gateway, "_generate_keypair", side_effect=OSError("disk full")):
            await gateway._rotate_key()
        assert gateway._healing_budget == 2

    @pytest.mark.asyncio
    async def test_budget_exhaustion_triggers_alert(self, mock_pyoqs):
        """Exhausting the budget must trigger an alert."""
        gateway = qkg.QuantumKeyDistributionGateway()
        gateway._consensus_params = qkg.CRAConsensusParameters(
            self_healing_budget=1
        )
        await gateway.initialize()
        with patch.object(gateway, "_generate_keypair", side_effect=OSError("disk full")):
            with pytest.raises(RuntimeError, match="self-healing budget exhausted"):
                await gateway._rotate_key()

    @pytest.mark.asyncio
    async def test_budget_reset_after_success(self, mock_pyoqs):
        """Successful rotations must reset the budget."""
        gateway = qkg.QuantumKeyDistributionGateway()
        gateway._consensus_params = qkg.CRAConsensusParameters(
            self_healing_budget=3
        )
        await gateway.initialize()
        # Fail once
        with patch.object(gateway, "_generate_keypair", side_effect=OSError("disk full")):
            await gateway._rotate_key()
        assert gateway._healing_budget == 2
        # Succeed
        await gateway._rotate_key()
        assert gateway._healing_budget == 3


