    async def test_state_locking(self, mock_pyoqs):
        """State must be locked during transaction."""
        gateway = qkg.QuantumKeyDistributionGateway()
        await gateway.initialize()
        async with gateway._state_lock:
            # Attempt to rotate should fail or wait
            with pytest.raises(asyncio.TimeoutError):
                await asyncio.wait_for(gateway._rotate_key(), timeout=0.1)


