class KeyRotationStateMachine(RuleBasedStateMachine):
    """Stateful property test for key rotation invariants."""

    def __init__(self):
        super().__init__()
        self.gateway = qkg.QuantumKeyDistributionGateway()
        self.rotation_count = 0
        self.failure_count = 0

    @rule()
    def initialize(self):
        """Initialize the gateway."""
        asyncio.get_event_loop().run_until_complete(self.gateway.initialize())

    @rule()
    def rotate(self):
        """Attempt a key rotation."""
        try:
            asyncio.get_event_loop().run_until_complete(self.gateway._rotate_key())
            self.rotation_count += 1
        except (OSError, RuntimeError):
            self.failure_count += 1

    @rule(ttl=st.floats(min_value=0.01, max_value=10.0))
    def set_ttl(self, ttl):
        """Set a random TTL."""
        self.gateway._consensus_params = qkg.CRAConsensusParameters(
            key_rotation_ttl_seconds=ttl
        )

    @invariant()
    def budget_never_negative(self):
        """INV-003: Budget must never go negative."""
        assert self.gateway._healing_budget >= 0

    @invariant()
    def rotation_count_matches(self):
        """Rotation count must be consistent."""
        assert self.rotation_count >= 0

    @invariant()
    def active_key_always_valid(self):
        """Active key must always have valid structure."""
        if hasattr(self.gateway, "_active_key"):
            assert self.gateway._active_key.key_id is not None
            assert self.gateway._active_key.public_key is not None


TestKeyRotationStateMachine = KeyRotationStateMachine.TestCase


