class TestChaosResilience:
    """Validate resilience under failure injection."""

    @pytest.mark.asyncio
    async def test_disk_full_during_rotation(self, mock_pyoqs):
        """Disk full errors must not corrupt state."""
        gateway = qkg.QuantumKeyDistributionGateway()
        await gateway.initialize()
        original_key = gateway._active_key
        with patch.object(gateway, "_generate_keypair", side_effect=OSError("disk full")):
            with pytest.raises(OSError):
                await gateway._rotate_key()
        # State must remain consistent
        assert gateway._active_key == original_key

    @pytest.mark.asyncio
    async def test_timeout_during_encapsulation(self, mock_pyoqs):
        """Timeouts must be handled gracefully."""
        gateway = qkg.QuantumKeyDistributionGateway()
        await gateway.initialize()
        with patch.object(gateway, "_encapsulate", side_effect=asyncio.TimeoutError):
            with pytest.raises(asyncio.TimeoutError):
                await gateway._rotate_key()
        # Budget should be decremented
        assert gateway._healing_budget == 2

    @pytest.mark.asyncio
    async def test_corrupted_shared_secret(self, mock_pyoqs):
        """Corrupted shared secrets must be detected."""
        gateway = qkg.QuantumKeyDistributionGateway()
        await gateway.initialize()
        # Corrupt the shared secret
        gateway._active_key.shared_secret = b"corrupted" * 32
        with pytest.raises(ValueError, match="shared secret verification failed"):
            await gateway._verify_shared_secret()


