class TestSecurity:
    """Validate security-critical behaviors."""

    def test_private_key_not_in_logs(self, caplog):
        """Private keys must never appear in logs."""
        with caplog.at_level(logging.DEBUG):
            km = qkg.KeyMaterial(
                key_id="test",
                public_key=b"pk" * 32,
                private_key=b"SECRET_PRIVATE_KEY" * 10,
                shared_secret=b"ss" * 32,
                created_at=time.time(),
                expires_at=time.time() + 5.0,
                state=qkg.KeyState.ACTIVE,
            )
            logger.debug("Key material: %s", km)
        assert "SECRET_PRIVATE_KEY" not in caplog.text

    @pytest.mark.asyncio
    async def test_memory_scrubbing(self, mock_pyoqs):
        """Private keys must be scrubbed from memory after use."""
        gateway = qkg.QuantumKeyDistributionGateway()
        await gateway.initialize()
        # Get a reference to the private key buffer
        sk_buffer = (ctypes.c_char * len(gateway._active_key.private_key)).from_buffer_copy(
            gateway._active_key.private_key
        )
        # Trigger rotation which should scrub old key
        await gateway._rotate_key()
        # The old buffer should be zeroed
        assert all(b == 0 for b in sk_buffer), "Private key buffer not scrubbed"


